using FreshFoundation;
using System.Text.Json;
internal static class HistoryChecks
{
    internal static int Run()
    {
        string folder=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-r10-history-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string slot=Path.Combine(folder,"data001Slot.bin");File.WriteAllBytes(slot,WorkspaceSyntheticSamples.Slot(transferFixture:true));File.WriteAllBytes(Path.Combine(folder,"data00-1.bin"),WorkspaceSyntheticSamples.SystemFile());int failed=0;var cases=new List<object>();void Check(bool c){if(!c)throw new Exception("History assertion");}void Test(string name,Action a){try{a();cases.Add(new{name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name,status="FAIL",error=e.Message});}}DirectoryEditor Fresh(){var g=new DirectoryEditor();g.OpenDirectory(folder);g.OpenSlot(slot);return g;}
        Test("transfer grouped undo redo totals export",()=>{var g=Fresh();g.ApplyDomain(d=>d.TransferItem(0,1,3));g.Undo();Check(g.StagedCount==0);g.Redo();Check(g.Domain!.Inventory()[0].Quantity==7&&g.Domain.Inventory()[1].Quantity==3&&g.Domain.Inventory().Sum(i=>i.Quantity)==14);string output=Path.Combine(folder,"redo.bin");g.Slot.Export(output,folder);var w=new EditorWorkspace();w.Open(output);Check(new DomainEditor(w).Inventory()[1].Quantity==3);});
        Test("equipment combined history",()=>{var g=Fresh();g.ApplyDomain(d=>d.ApplyEquipmentDraft(d.ReadEquipmentDraft(3),[0,0,0],[new(5,7),new(2,3)]));g.Undo();Check(g.StagedCount==0);g.Redo();Check(g.Domain!.Talisman(3).Pairs[0]==new SkillPair(5,7)&&g.Domain.DecorationIds(3).All(i=>i==0));});
        Test("money system grouped history",()=>{var g=Fresh();g.SetMoney(1500);g.Undo();Check(g.Domain!.Character().Money==2000&&g.CachedMoney==2000);g.Redo();Check(g.Domain.Character().Money==1500&&g.CachedMoney==1500);});
        Test("multiple actions and replacement branch",()=>{var g=Fresh();g.SetMoney(1500);g.ApplyDomain(d=>d.SetPoints(4000));g.Undo();g.Undo();g.Redo();Check(g.Domain!.Character().Money==1500&&g.Domain.Character().Points==5000);g.ApplyDomain(d=>d.SetPoints(3000));Check(!g.CanRedo);});
        Test("failed and noop retain redo",()=>{var g=Fresh();g.SetMoney(1500);g.Undo();try{g.SetMoney(2001);}catch(ArgumentException){}Check(g.CanRedo);try{g.ApplyDomain(d=>{d.SetMoney(1000);throw new InvalidOperationException("synthetic failed group");});}catch(InvalidOperationException){}Check(g.CanRedo&&g.StagedCount==0&&g.Domain!.Character().Money==2000);g.SetMoney(2000);g.ApplyDomain(d=>{var draft=d.ReadEquipmentDraft(3);d.ApplyEquipmentDraft(draft,draft.Decorations,draft.Pairs);});Check(g.CanRedo);g.Redo();Check(g.CachedMoney==1500);});
        Test("clear undo redo grouped",()=>{var g=Fresh();g.SetMoney(1500);g.ApplyDomain(d=>d.TransferItem(0,1,2));int count=g.StagedCount;g.Clear();Check(g.StagedCount==0);g.Undo();Check(g.StagedCount==count);g.Redo();Check(g.StagedCount==0);});
        Test("document and directory context reset",()=>{var g=Fresh();g.SetMoney(1500);g.Undo();g.OpenSlot(slot);Check(!g.CanRedo&&!g.CanUndo);g.SetMoney(1500);g.OpenDirectory(folder);Check(!g.CanRedo&&!g.CanUndo&&g.StagedCount==0);});
        Test("change review copies original/current and never aliases",()=>{var g=Fresh();g.SetMoney(1500);var rows=g.ReviewChanges();Check(rows.Count==2&&rows.All(r=>r.Capability.Contains("Money")));var money=rows.First();Check(BitConverter.ToInt32(money.OriginalBytes)==2000&&BitConverter.ToInt32(money.CurrentBytes)==1500);money.CurrentBytes[0]=0;Check(g.Domain!.Character().Money==1500);g.Clear();Check(g.ReviewChanges().Count==0);});
        File.WriteAllText("test-results-r10-history.json",JsonSerializer.Serialize(new{atUtc=DateTimeOffset.UtcNow,scope="Synthetic existing operations only",failed,cases},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"History cases={cases.Count}; failures={failed}");return failed==0?0:1;
    }
}
